robust_survreg_det_starts = function(surv_object, cov_matrix_or_vector, dist = "lognormal", num_max_iter = 50) {
  surv_reg_formula = surv_object ~ .
  X_mat = as.matrix(cov_matrix_or_vector)
  X_mat = EDI:::drop_highly_correlated_cols(X_mat)$M
  X_mat = EDI:::drop_linearly_dependent_cols(X_mat)$M
  dat = data.frame(X_mat)
  ctrl = survival::survreg.control(maxiter = 100, rel.tolerance = 1e-9, outer.max = 10)
  try_fit = function(init) {
    mod = tryCatch(suppressWarnings(
      if (is.null(init)) survival::survreg(surv_reg_formula, data = dat, dist = dist, control = ctrl)
      else survival::survreg(surv_reg_formula, data = dat, dist = dist, init = init, control = ctrl)
    ), error = function(e) NULL)
    if (!is.null(mod) && !any(is.na(mod$coefficients))) mod else NULL
  }
  mod = try_fit(NULL)                                  # survreg's own init(x, weights)
  if (!is.null(mod)) return(mod)
  lt = log(surv_object[, 1])
  start = c(mean(lt), rep(0, ncol(dat)))                # moment start: intercept = mean log-time
  mod = try_fit(start)
  if (!is.null(mod)) return(mod)
  sc = pmax(abs(start), 1) * 0.5
  set.seed(20261022L)
  for (i in seq_len(num_max_iter - 2L)) {
    mod = try_fit(start + stats::rnorm(length(start)) * sc)
    if (!is.null(mod)) return(mod)
  }
  NULL
}
bench_run = function(d) {
  mod = robust_survreg_det_starts(d$surv, d$x, dist = d$dist)
  as.numeric(c(mod$coefficients, log(mod$scale)))
}
